package org.mockito.internal;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.creation.MockSettingsImpl;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.InvocationContainer;
import org.mockito.internal.invocation.InvocationMatcher;
import org.mockito.internal.invocation.MatchersBinder;
import org.mockito.internal.matcher.InvocationMatcher;
import org.mockito.internal.matcher.MatchersBinder;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import org.mockito.internal.settings.MockSettingsImpl;
import org.mockito.internal.stubbing.Answer;
import org.mockito.internal.stubbing.InvocationContainer;
import org.mockito.internal.stubbing.InvocationContainerImpl;
import org.mockito.internal.stubbing.OngoingStubbingImpl;
import org.mockito.internal.stubbing.StubbedInvocationMatcher;
import org.mockito.internal.stubbing.VoidMethodStubbableImpl;
import org.mockito.internal.verification.MockAwareVerificationMode;
import org.mockito.internal.verification.VerificationDataImpl;
import org.mockito.internal.verification.VerificationMode;
import org.mockito.stubbing.Answer;
import org.mockito.stubbing.VoidMethodStubbable;
import org.mockito.verification.VerificationMode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class MockHandler_handle_TriageGen0Test {

    private MockHandler mockHandler;
    private Invocation invocation;
    private InvocationContainer invocationContainerImpl;
    private MatchersBinder matchersBinder;
    private MockingProgress mockingProgress;
    private MockSettingsImpl mockSettings;
    private InvocationMatcher invocationMatcher;

    @Before
    public void setUp() throws Throwable {
        mockHandler = spy(new MockHandler(mockSettings = mock(MockSettingsImpl.class)));
        invocation = mock(Invocation.class);
        invocationContainerImpl = mock(InvocationContainer.class);
        matchersBinder = mock(MatchersBinder.class);
        mockingProgress = mock(MockingProgress.class);
        invocationMatcher = mock(InvocationMatcher.class);

        // Inject mocks into the handler via reflection or by ensuring the spy captures calls
        // Since we are testing the internal logic, we assume these dependencies are available
        // In a real Mockito test environment, these are fields in MockHandler
        setInternalState(mockHandler, "invocationContainerImpl", invocationContainerImpl);
        setInternalState(mockHandler, "matchersBinder", matchersBinder);
        setInternalState(mockHandler, "mockingProgress", mockingProgress);
        setInternalState(mockHandler, "mockSettings", mockSettings);

        when(matchersBinder.bindMatchers(any(), any())).thenReturn(invocationMatcher);
    }

    @Test
    public void testHandle_StubbingVoids() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(true);

        Object result = mockHandler.handle(invocation);

        verify(invocationContainerImpl).setMethodForStubbing(invocationMatcher);
        assertNull(result);
    }

    @Test
    public void testHandle_VerificationSuccess() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(false);
        VerificationMode verificationMode = mock(MockAwareVerificationMode.class);
        when(mockingProgress.pullVerificationMode()).thenReturn(verificationMode);
        when(verificationMode.getMock()).thenReturn(invocation.getMock());
        when(mockingProgress.getArgumentMatcherStorage()).thenReturn(mock(org.mockito.internal.MatcherStorage.class));

        Object result = mockHandler.handle(invocation);

        verify(verificationMode).verify(any(VerificationDataImpl.class));
        assertNull(result);
    }

    @Test
    public void testHandle_VerificationFailMockMismatch() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(false);
        VerificationMode verificationMode = mock(MockAwareVerificationMode.class);
        when(mockingProgress.pullVerificationMode()).thenReturn(verificationMode);

        Invocation differentMockInvocation = mock(Invocation.class);
        when(verificationMode.getMock()).thenReturn(differentMockInvocation); // Different mock

        mockHandler.handle(invocation);

        // Should not call verify because mock doesn't match
        verify(verificationMode, never()).verify(any());
        // Should proceed to stubbing logic
        verify(invocationContainerImpl).setInvocationForPotentialStubbing(invocationMatcher);
    }

    @Test
    public void testHandle_VerificationNonMockAware() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(false);
        VerificationMode verificationMode = mock(VerificationMode.class); // Not MockAware
        when(mockingProgress.pullVerificationMode()).thenReturn(verificationMode);

        mockHandler.handle(invocation);

        verify(invocationContainerImpl).setInvocationForPotentialStubbing(invocationMatcher);
    }

    @Test
    public void testHandle_StubbedInvocationFound() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(false);
        when(mockingProgress.pullVerificationMode()).thenReturn(null);

        StubbedInvocationMatcher stubbedInvocation = mock(StubbedInvocationMatcher.class);
        when(invocationContainerImpl.findAnswerFor(invocation)).thenReturn(stubbedInvocation);
        when(stubbedInvocation.answer(invocation)).thenReturn("stubbed_answer");

        Object result = mockHandler.handle(invocation);

        verify(stubbedInvocation).captureArgumentsFrom(invocation);
        assertEquals("stubbed_answer", result);
    }

    @Test
    public void testHandle_DefaultAnswer() throws Throwable {
        when(invocationContainerImpl.hasAnswersForStubbing()).thenReturn(false);
        when(mockingProgress.pullVerificationMode()).thenReturn(null);
        when(invocationContainerImpl.findAnswerFor(invocation)).thenReturn(null);

        Answer defaultAnswer = mock(Answer.class);
        when(mockSettings.getDefaultAnswer()).thenReturn(defaultAnswer);
        when(defaultAnswer.answer(invocation)).thenReturn("default_answer");

        Object result = mockHandler.handle(invocation);

        verify(invocationContainerImpl).resetInvocationForPotentialStubbing(invocationMatcher);
        assertEquals("default_answer", result);
    }

    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
